-- This migration adds 6 Band 4 questions to bring the total to 10.
--
-- 6 questions: target_grade=4, difficulty_band=4, domain=prehistoric_denmark, is_active=true
-- Distribution: Kildefortolkning(2) + Historisk betydning(2) + Evaluering & moderne relevans(2)
